+    public ElliottTrendBiasIndicator trendBias() {
+        if (trendBiasIndicator == null) {
+            trendBiasIndicator = new ElliottTrendBiasIndicator(scenarios());
+        }
+        return trendBiasIndicator;
+    }
+
